import { Body, Controller, Delete, Param, ParseIntPipe, Patch, Post, Get, Query, Req, UseGuards } from '@nestjs/common';
import { RestaurantOwnerGuard } from '../auth/restaurant-owner.guard';
import { MotoboyService } from './motoboy.service';
import type { MotoboyPeloRestauranteBody } from './motoboy.service';

@Controller('restaurante/motoboys')
@UseGuards(RestaurantOwnerGuard)
export class RestauranteMotoboysController {
  constructor(private service: MotoboyService) {}

  @Get()
  listar(@Req() req: any) {
    return this.service.listar(req.restaurantId);
  }

  // Cadastro direto de motoboy próprio do estabelecimento (não passa por
  // autocadastro/aprovação da plataforma/solicitação de afiliação).
  @Post()
  criar(@Body() body: MotoboyPeloRestauranteBody, @Req() req: any) {
    return this.service.criarPeloRestaurante(req.restaurantId, body);
  }

  @Patch(':motoboyId')
  editar(@Param('motoboyId', ParseIntPipe) motoboyId: number, @Body() body: MotoboyPeloRestauranteBody, @Req() req: any) {
    return this.service.editarPeloRestaurante(motoboyId, req.restaurantId, body);
  }

  @Delete(':motoboyId')
  excluir(@Param('motoboyId', ParseIntPipe) motoboyId: number, @Req() req: any) {
    return this.service.excluirPeloRestaurante(motoboyId, req.restaurantId);
  }

  @Patch(':motoboyId/bloquear')
  bloquear(@Param('motoboyId', ParseIntPipe) motoboyId: number, @Body() body: { bloqueado: boolean }, @Req() req: any) {
    return this.service.bloquearAfiliacao(motoboyId, req.restaurantId, !!body?.bloqueado);
  }

  @Get('solicitacoes/count')
  solicitacoesCount(@Req() req: any) {
    return this.service.contarSolicitacoesPendentes(req.restaurantId);
  }

  @Get('solicitacoes')
  solicitacoes(@Query('status') status: 'pendente' | 'aceito' | 'recusado' | undefined, @Req() req: any) {
    return this.service.listarSolicitacoes(req.restaurantId, status ?? 'pendente');
  }

  @Patch('solicitacoes/:id/aceitar')
  aceitar(@Param('id', ParseIntPipe) id: number, @Req() req: any) {
    return this.service.aceitarSolicitacao(id, req.restaurantId);
  }

  @Patch('solicitacoes/:id/recusar')
  recusar(@Param('id', ParseIntPipe) id: number, @Body() body: { motivo?: string }, @Req() req: any) {
    return this.service.recusarSolicitacao(id, req.restaurantId, body?.motivo);
  }

  @Patch('solicitacoes/:id/revisar')
  revisar(@Param('id', ParseIntPipe) id: number, @Req() req: any) {
    return this.service.revisarSolicitacao(id, req.restaurantId);
  }

  @Patch(':motoboyId/remover')
  remover(@Param('motoboyId', ParseIntPipe) motoboyId: number, @Req() req: any) {
    return this.service.removerAfiliacao(motoboyId, req.restaurantId);
  }

  // redirectTo dinâmico a partir de quem chamou (mesmo padrão de RestaurantOwnerGuard
  // lendo Origin/Referer) — sem isso, cai no Site URL padrão do projeto Supabase.
  private redirectToDoRequest(req: any): string | undefined {
    const origem = req.headers['origin'] || req.headers['referer'];
    if (!origem) return undefined;
    const base = String(origem).replace(/\/$/, '');
    return `${base}/reset-password`;
  }

  @Post(':motoboyId/gerar-link-senha')
  gerarLinkSenha(@Param('motoboyId', ParseIntPipe) motoboyId: number, @Req() req: any) {
    return this.service.gerarLinkRedefinicaoSenha(motoboyId, req.restaurantId, this.redirectToDoRequest(req));
  }

  @Post(':motoboyId/enviar-link-senha-email')
  enviarLinkSenhaEmail(@Param('motoboyId', ParseIntPipe) motoboyId: number, @Req() req: any) {
    return this.service.enviarLinkRedefinicaoSenhaPorEmail(motoboyId, req.restaurantId, this.redirectToDoRequest(req));
  }

  @Patch(':pedidoId/atribuir')
  atribuir(
    @Param('pedidoId', ParseIntPipe) pedidoId: number,
    @Body() body: { motoboy_id: number },
    @Req() req: any,
  ) {
    return this.service.atribuir(pedidoId, req.restaurantId, body.motoboy_id);
  }
}

const BASE_LINKS = [
  { label: 'Dashboard', path: '/restaurante', icon: 'LayoutDashboard' },
  { label: 'Conferências', path: '/restaurante/relatorios', icon: 'BarChart3' },
  { label: 'Produtos', path: '/restaurante/produtos', icon: 'Package' },
  { label: 'Clientes', path: '/restaurante/clientes', icon: 'UserRound' },
  { label: 'Financeiro', path: '/restaurante/financeiro', icon: 'Wallet' },
  { label: 'Caixa', path: '/restaurante/caixa', icon: 'PiggyBank' },
  { label: 'Designer', path: '/restaurante/aparencia', icon: 'Paintbrush' },
  { label: 'Cardápio Digital', path: '/restaurante/cardapio-digital', icon: 'BookOpen' },
  { label: 'Plano', path: '/restaurante/plano', icon: 'CreditCard' },
  { label: 'Sessão', path: '/restaurante/sessao', icon: 'Clock' },
];

// Servem tanto Delivery quanto Salão — só somem se a empresa não tem NENHUM módulo ativo.
const COMPARTILHADO_LINKS = [
  { label: 'Cozinha', path: '/restaurante/cozinha', icon: 'ChefHat' },
  { label: 'Combos', path: '/restaurante/combos', icon: 'Boxes' },
  { label: 'Pedidos', path: '/restaurante/pedidos', icon: 'ClipboardList' },
];

const DELIVERY_LINKS = [
  { label: 'Delivery', path: '/restaurante/delivery', icon: 'Truck' },
  { label: 'Entregas', path: '/restaurante/entregas', icon: 'Bike' },
  { label: 'Motoboys', path: '/restaurante/motoboys', icon: 'Users' },
  { label: 'Impulsionar', path: '/restaurante/impulsionar', icon: 'Rocket' },
];

const COPA_LINKS = [
  { label: 'Produção', path: '/restaurante/producao', icon: 'CookingPot' },
  { label: 'Bar', path: '/restaurante/bar', icon: 'Beer' },
];

const SALAO_LINKS = [
  { label: 'Salão', path: '/restaurante/salao', icon: 'UtensilsCrossed' },
  { label: 'Venda Balcão', path: '/restaurante/venda-balcao', icon: 'ShoppingCart' },
  { label: 'Chamada', path: '/restaurante/chamada', icon: 'Volume2' },
  { label: 'Garçons', path: '/restaurante/garcons', icon: 'Contact' },
  { label: 'Mesas', path: '/restaurante/mesas', icon: 'Table2' },
  { label: 'Impressoras', path: '/restaurante/impressoras', icon: 'Printer' },
];

// Pontos de preparo customizados (Churrasqueira, Drinks...) usam o mesmo requisito de
// visibilidade da Cozinha — precisam de algum módulo ativo pra fazer sentido no menu.
const PONTOS_PREPARO_CADASTRO = { label: 'Pontos de Preparo', path: '/restaurante/pontos-preparo', icon: 'LayoutGrid' };

// Estabelecimento tipo ≠ Restaurante (farmácia, material de construção...) chama
// o entregador de "Entregadores" no menu, em vez de "Motoboys" (termo mais
// específico de delivery de comida).
export const getRestauranteNavLinks = (moduloDelivery, moduloSalao, pontosPreparo = [], tipoRestaurante = true) => {
  const temAlgumModulo = moduloDelivery || moduloSalao;
  const deliveryLinks = tipoRestaurante
    ? DELIVERY_LINKS
    : DELIVERY_LINKS.map((l) => (l.path === '/restaurante/motoboys' ? { ...l, label: 'Entregadores' } : l));
  const links = [
    ...BASE_LINKS.slice(0, 2), // Dashboard, Relatórios
    ...(moduloDelivery ? deliveryLinks.slice(0, 1) : []), // Delivery
    ...(temAlgumModulo ? COMPARTILHADO_LINKS.slice(0, 1) : []), // Cozinha
    ...(temAlgumModulo ? [PONTOS_PREPARO_CADASTRO, ...pontosPreparo] : []), // Cadastro + pontos criados
    ...(moduloSalao ? COPA_LINKS : []), // Produção, Bar
    ...BASE_LINKS.slice(2, 3), // Produtos
    ...(temAlgumModulo ? COMPARTILHADO_LINKS.slice(1) : []), // Combos, Pedidos
    ...(moduloDelivery ? deliveryLinks.slice(1) : []), // Entregas, Motoboys/Entregadores
    ...BASE_LINKS.slice(3), // Clientes...Sessão
    ...(moduloSalao ? SALAO_LINKS : []), // Salão, Garçons, Impressoras
  ];
  // Menu lateral em ordem alfabética (pedido do usuário) — a ordem acima só
  // controla quais links entram conforme os módulos ativos. Dashboard fica
  // fixo no topo, fora da ordenação.
  const [dashboard, resto] = [links.find((l) => l.path === '/restaurante'), links.filter((l) => l.path !== '/restaurante')];
  resto.sort((a, b) => a.label.localeCompare(b.label, 'pt-BR'));
  return dashboard ? [dashboard, ...resto] : resto;
};

