1	import React, { useState } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import { AnimatePresence } from 'framer-motion';
4	import Icon from '../AppIcon';
5	import RestauranteSidebar from './RestauranteSidebar';
6	import MobileMenu from './MobileMenu';
7	import { ThemeToggle } from '../../contexts/ThemeContext';
8	import { useAuth } from '../../contexts/AuthContext';
9	import { useMinhaLojaSlug } from '../../hooks/useMinhaLojaSlug';
10	import { useMinhaLojaLogo } from '../../hooks/useMinhaLojaLogo';
11	import { useModulosEmpresa } from '../../hooks/useModulosEmpresa';
12	import { useSolicitacoesMotoboyCount } from '../../hooks/useSolicitacoesMotoboyCount';
13	import { usePontosPreparoLinks } from '../../hooks/usePontosPreparoLinks';
14	import { useRestauranteFavoritos } from '../../hooks/useRestauranteFavoritos';
15	import { getRestauranteNavLinks } from '../../config/restauranteNavLinks';
16	
17	// Header compartilhado de toda a área /restaurante/*. Substitui o header
18	// duplicado (e divergente) que cada página tinha antes — ver plano
19	// "Layout compartilhado + favoritos na topbar".
20	// Bolinha de status do plano na barra superior — verde (em dia), laranja
21	// (vencendo em breve ou vencida mas dentro da tolerância), vermelha (bloqueado).
22	const DIAS_ALERTA_VENCIMENTO = 5;
23	
24	// Ícones dos favoritos começam grandes/bem visíveis e só encolhem conforme a
25	// quantidade aumenta, pra continuar cabendo numa linha só na topbar.
26	const tamanhoFavoritos = (qtd) => {
27	  if (qtd <= 3) return { icone: 35, padding: 'p-3' };
28	  if (qtd <= 5) return { icone: 31, padding: 'p-2.5' };
29	  if (qtd <= 7) return { icone: 27, padding: 'p-2' };
30	  return { icone: 23, padding: 'p-1.5' };
31	};
32	
33	const PlanoStatusDot = ({ planoStatus, onClick }) => {
34	  if (!planoStatus || !planoStatus.plano_nome) return null;
35	
36	  const diasAteVencer = planoStatus.proxima_cobranca
37	    ? Math.ceil((new Date(planoStatus.proxima_cobranca) - new Date()) / 86400000)
38	    : null;
39	
40	  let cor = 'bg-green-500';
41	  let texto = 'Plano em dia';
42	  if (planoStatus.bloqueado) {
43	    cor = 'bg-red-500';
44	    texto = `Painel bloqueado — fatura vencida há ${planoStatus.dias_atraso} dia(s)`;
45	  } else if (planoStatus.dias_atraso > 0) {
46	    cor = 'bg-orange-500';
47	    texto = `Fatura vencida há ${planoStatus.dias_atraso} dia(s) — regularize`;
48	  } else if (diasAteVencer != null && diasAteVencer <= DIAS_ALERTA_VENCIMENTO) {
49	    cor = 'bg-orange-500';
50	    texto = `Próxima cobrança em ${diasAteVencer} dia(s)`;
51	  }
52	
53	  return (
54	    <button onClick={onClick} title={texto}
55	      className="p-2 rounded-lg hover:bg-[#F4F4F5] dark:hover:bg-[#27272A] flex-shrink-0">
56	      <span className={`block w-2.5 h-2.5 rounded-full ${cor} ${planoStatus.bloqueado ? 'animate-pulse' : ''}`} />
57	    </button>
58	  );
59	};
60	
61	const RestauranteHeader = ({ active, title, subtitle, onRefresh }) => {
62	  const navigate = useNavigate();
63	  const { signOut, planoStatus } = useAuth();
64	  const slugLoja = useMinhaLojaSlug();
65	  const logoUrl = useMinhaLojaLogo();
66	  const { moduloDelivery, moduloSalao, tipoRestaurante } = useModulosEmpresa();
67	  const pendentesMotoboy = useSolicitacoesMotoboyCount();
68	  const pontosPreparoLinks = usePontosPreparoLinks();
69	  const { favoritos, toggleFavorito, isFavorito, mostrarNomes, toggleMostrarNomes } = useRestauranteFavoritos();
70	  const [sidebarAberto, setSidebarAberto] = useState(false);
71	  const [menuAberto, setMenuAberto] = useState(false);
72	  const [atualizando, setAtualizando] = useState(false);
73	
74	  // Botão de atualizar dados sem recarregar a página inteira — o spin mínimo de
75	  // 400ms é só feedback visual, mesmo se o onRefresh do caller for instantâneo.
76	  const handleRefresh = async () => {
77	    if (!onRefresh || atualizando) return;
78	    setAtualizando(true);
79	    try {
80	      await onRefresh();
81	    } finally {
82	      setTimeout(() => setAtualizando(false), 400);
83	    }
84	  };
85	
86	  const links = getRestauranteNavLinks(moduloDelivery, moduloSalao, pontosPreparoLinks, tipoRestaurante);
87	  const linksFavoritos = links.filter((l) => favoritos.includes(l.path));
88	
89	  return (
90	    <>
91	      <header className="sticky top-0 z-40 bg-white dark:bg-[#18181B] border-b border-[#E4E4E7] dark:border-[#3F3F46] px-6 py-4 flex items-center justify-between gap-3">
92	        <div className="flex items-center gap-2 min-w-0">
93	          {logoUrl
94	            ? <img src={logoUrl} alt="" className="w-8 h-8 rounded-lg object-cover flex-shrink-0" />
95	            : <div className="w-8 h-8 rounded-lg bg-[#FF441F]/10 flex items-center justify-center flex-shrink-0"><Icon name="UtensilsCrossed" size={16} className="text-[#FF441F]" /></div>}
96	          <div className="min-w-0">
97	            <h1 className="text-xl font-bold text-[#18181B] dark:text-[#F4F4F5] truncate">{title}</h1>
98	            {subtitle && <p className="text-sm text-[#71717A] dark:text-[#A1A1AA] truncate">{subtitle}</p>}
99	          </div>
100	        </div>
101	
102	        {linksFavoritos.length > 0 && (
103	          <div className="hidden md:flex items-center gap-1.5 min-w-0">
104	            <div className="flex items-center gap-1.5 overflow-x-auto">
105	              {linksFavoritos.map((l) => {
106	                const { icone, padding } = mostrarNomes ? { icone: 13, padding: 'px-3 py-1.5' } : tamanhoFavoritos(linksFavoritos.length);
107	                return (
108	                  <button key={l.path} onClick={() => navigate(l.path)} title={l.label}
109	                    className={`relative flex items-center gap-1.5 ${padding} text-xs font-semibold rounded-full whitespace-nowrap transition-colors ${
110	                      l.path === active ? 'bg-[#FF441F] text-white' : 'bg-[#F4F4F5] dark:bg-[#27272A] text-[#27272A] dark:text-[#F4F4F5] hover:bg-[#E4E4E7] dark:hover:bg-[#3F3F46]'
111	                    }`}>
112	                    <Icon name={l.icon} size={icone} /> {mostrarNomes && l.label}
113	                    {l.path === '/restaurante/motoboys' && pendentesMotoboy > 0 && (
114	                      <span className="absolute -top-1.5 -right-1.5 min-w-[18px] h-[18px] px-1 flex items-center justify-center bg-red-500 text-white text-[10px] font-bold rounded-full">
115	                        {pendentesMotoboy}
116	                      </span>
117	                    )}
118	                  </button>
119	                );
120	              })}
121	            </div>
122	            <button onClick={toggleMostrarNomes} title={mostrarNomes ? 'Mostrar só ícones' : 'Mostrar nomes'}
123	              className="p-1.5 rounded-full flex-shrink-0 text-[#71717A] dark:text-[#A1A1AA] hover:bg-[#F4F4F5] dark:hover:bg-[#27272A]">
124	              <Icon name={mostrarNomes ? 'ChevronsLeftRight' : 'ChevronsRightLeft'} size={13} />
125	            </button>
126	          </div>
127	        )}
128	
129	        <div className="flex items-center gap-2 flex-shrink-0">
